// ?isLocationSafe@AIPlayer@@QAE_NPBUCoord3D@@PBVThingTemplate@@@Z
// partial score=0.3325 date=2026-09-28
// cl: /DNDEBUG /DWIN32 /MD /EHsc
// readable body of ?isLocationSafe@AIPlayer@@QAE_NPBUCoord3D@@PBVThingTemplate@@@Z:
// inputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/GameEngine/Source/GameLogic/AI/AIPlayer.cpp
//
// AIPlayer::isLocationSafe, 0x00163030, 388 bytes.  Compiles to 393 bytes with
// 249 non-relocation byte differences, probe shape 0.941, and -- NEW THIS
// SESSION -- the EXACT retail 0xB0 frame.  It is NOT exact.  The inherited bank
// was 393/251 with a 0xC4 frame.
//
// Identity is proved: the matched caller
// ?isSupplySourceSafe@AIPlayer@@QAE_NH@Z (AIPlayer.cpp:1006) calls it and
// symbols.csv pins the named ILT at 0x0003E504 here.  Zero Hour's AIPlayer.cpp
// :998 is the same function with an array-of-filters filter set; BFME retail
// instead builds six filters on the stack, links them with five calls to
// PartitionFilter::link (0x009F2AE0) and hands the head to
// ThePartitionManager->getClosestObject (0x009F26A0).  The body ends in
// `ret 8` at +0x181.
//
// ============================================================================
// THE LEVER THAT MOVED THE BODY: give the TU the KindOf constructor's body
// ============================================================================
// Every prior verdict (13 of them) modelled the two KindOf filters with an
// extern constructor declaration and got a 0xC4 frame against retail's 0xB0.
// Making the 102-byte constructor at 0x00160BE0 VISIBLE IN THIS TU, defined
// out of line, collapses the frame to retail's exact 0xB0:
//
//   extern ctor, __declspec(nothrow)   393 B  frame 0xC4   (e0, inherited)
//   extern ctor, no nothrow            393 B  frame 0xDC   (e2)
//   ctor defined in this TU            393 B  frame 0xB0   (e1, banked)
//
// so `__declspec(nothrow)` is NOT the mechanism; callee visibility is.  This is
// the lever docs/shape_levers.md records under "Filter construction: visible
// non-retaining constructors", where the same move at 0x002622D0 let VC7.1
// reuse a six-word mask temporary's storage for the relationship filter once
// it could see that the real constructor copies both masks and retains
// neither.  It is the same callee-visibility mechanism as "A caller may rely
// on the visible callee preserving ECX"; no lifetime is being faked and the
// constructor below is the complete, independently matched 0x00160BE0 body.
//
// The visibility is load-bearing for the frame but is NOT what blocks the
// remaining 5 bytes, which is a register allocation (below).
//
// ============================================================================
// frame map -- machine-derived, not estimated
// ============================================================================
// Traced with an esp simulation over the real callee ret arities
// (0x00407E37 ret 8, 0x00DF2AE0 ret 4, 0x00DF26A0 ret 0x10) and cross-checked
// against FuncInfo 0x00DF3ABC (`tools/eh_info.py 0x00163030`: six unwind
// states, cleanup receivers -0x7c -0x44 -0xa0 -0x8c -0x94 -0xbc).  E is esp at
// entry, S = E-0xC4 is esp after `sub esp,0xb0; push ebx; push edi`, and
// F = S+8 = E-0xBC is the base of the 0xB0 local frame, which is exactly
// [F, F+0xB0).  Every object's slot below is read off the trace, and this
// build now agrees with all of them:
//
//   F+0x00..F+0x17  24-byte KindOf mask temporary, REUSED as filterTeam
//   F+0x18          radius (fld tthing+0x70 ; fadd [AiData+0x84])
//   F+0x1C..F+0x27  filterInsignificant, vtable 0x010956E4, two Bools
//   F+0x28..F+0x2F  filterAlive, vtable 0x01083B80
//   F+0x30..F+0x3F  filterPlayer, vtable 0x0109685C
//   F+0x40..F+0x77  filterHarvesters, out-of-line ctor 0x00160BE0
//   F+0x78..F+0xAF  filterDozer, the same ctor
//
// The eight objects tile 0xB0 exactly, so retail performs exactly ONE
// stack-slot reuse: filterTeam (0x14 bytes) takes the 24-byte mask
// temporary's slot.  The mask's last write is at +0xB4 and the team's first
// at +0xF5, so the intervals really are disjoint.  Four independent
// confirmations of the same map, all reproduced by this build:
//   * the mask pointer handed to the 0x00160BE0 ctor is the same slot in both
//     calls -- `lea edx,[F+0x00]` at 0x00163062 and 0x00163098;
//   * the radius is stored at F+0x18 and reloaded from F+0x18 at 0x00163151;
//   * 0x00163149 re-reads the FIRST argument (pos) from E+4, not the second;
//   * the -0xbc cleanup (state 5, ILT 0x00160D10) is one of the same
//     one-store vtable-reset stubs as the other five, so the object that
//     reuses the mask slot IS filterTeam, while the mask temporary itself has
//     no cleanup at all.
//
// The `push esi` at +0x58 is a mid-body SAVE of the incoming ESI, not a stack
// temp, and the arithmetic now closes on both paths.  With the save
// outstanding, esp is E-0xC8 at the epilogue, `pop esi` at +0x16A brings it to
// E-0xC4, and `mov ecx,[esp+0xB8]` at +0x16B reads E-0x0C -- the `push eax`
// that saved fs:[0] at +0x0D.  The false path jumps at +0x2E to +0x16B,
// skipping that pop, and reads the same E-0x0C.  `add esp, 0xBC` then lands on
// E on both paths.  So ESI is genuinely reused from +0x7D and genuinely has to
// be saved.
//
// ============================================================================
// the register plan, and the one thing still missing
// ============================================================================
// Retail's register plan: tthing in ECX, `this` in EDI, EBX as the zero
// constant, ECX also as the mask zero constant, EAX carrying 0x4000/0x10000
// and the AiData pointer, EDX as the mask pointer, and the two constructor
// return values in EAX (dozer) and ESI (harvesters).
//
// This build's plan: identical except `this` is in ESI, and BOTH constructor
// return values are discarded and rematerialised with `lea`.  That is the
// whole of the remaining 5 bytes; the accounting closes exactly:
//
//   ours  lea eax,[esp+0x48] ; push eax   (5)   retail  push esi           (1)
//   ours  lea ecx,[esp+0x84]              (7)   retail  mov ecx, eax       (2)
//   ours  -                                  retail  mov esi, eax         (2)
//   ours  -                                  retail  push esi (at +0x58)  (1)
//   ours  -                                  retail  pop  esi (at +0x16A) (1)
//   ours  pop esi ; pop ebx                (2)   retail  pop esi; pop edi; pop ebx (3)
//                                          +9                           -5
//
// Note the direction of the causality, which no earlier verdict had: this is
// NOT two problems.  The KindOf constructor's body pushes ESI and pops it, so
// it PRESERVES ESI.  Retail therefore keeps &filterHarvesters in ESI across
// the dozer constructor call.  That interval ( +0x7D .. +0x111 ) overlaps the
// one use of `this` ( the m_player read at +0x0D2 ), so `this` cannot be in
// ESI and moves to EDI -- which is also why retail has to spill the incoming
// ESI at +0x58 and restore it at +0x16A.  One missing register allocation
// produces the extra push esi, the extra pop edi, the lea/push pair and the
// two `mov esi,eax`-class moves, and accounts for all 5 bytes.
//
// The lever that fixed the register plan last session still holds and is still
// required: `AiData *const aiData = TheAI->m_aiData;` as its own local, before
// the radius statement.  Retail loads the AiData pointer into EAX twice for
// the fadd (`mov eax,[0x12EF214]` / `mov eax,[eax+0x14]` / `fadd [eax+0x84]`),
// which frees ECX to be the zero constant, which puts the mask pointer in EDX
// and keeps `or eax,0x4000` live until the store at +0x74.  Dropping the named
// local costs 60 differences and drops shape to 0.901 (measured h1).
//
// ============================================================================
// filter identities
// ============================================================================
// The four small filters store their vtable as literals rather than through a
// vtable symbol.  That is deliberate: dir32_addresses.csv records
// ??_7PartitionFilterPlayer@@6B@ at 0x0109688C while retail stores
// 0x0109685C, and there is no entry at all for 0x010956E4 or 0x01083B80, so a
// vtable symbol here would be a name whose address the gate would derive from
// this very body and therefore cannot check.  What is proved is the layout
// each class must have:
//
//   0x0109686C  vtable_lookup ties this vtable to PartitionFilterRejectByKindOf
//               (symbols.csv on ??_7PartitionFilterRejectByKindOf@@6B@), and
//               the matched sibling PartitionFilterRejectByKindOf::allow reads
//               its two masks at this+0x08 and this+0x20 -- the two offsets
//               the landed 0x00160BE0 constructor copies to.  The class is
//               therefore this filter, but the constructor's own parameter
//               TYPES are not proved (the landed body models them as plain
//               24-byte blocks), so the class below keeps an address-derived
//               name rather than claiming the real one.
//   0x0109685C  witnessed at +0x0008 m_player, +0x000C m_match.
//   0x010956E4  PartitionFilterInsignificantBuildings per the EA source
//               (AIPlayer.cpp:1043); its two Bools are true then false, the
//               Zero Hour (allowNonBuildings, allowInsignificant) order.
//   0x01083B80  PartitionFilterAlive per the EA source (AIPlayer.cpp:1035).
//   0x0109689C  PartitionFilterPlayerAffiliation, the one vtable that IS in
//               dir32_addresses.csv, witnessed at +0x0008 m_player,
//               +0x000C m_match, +0x0010 m_affiliation.
//
// Link order, each call's `this` being the later filter and its argument the
// earlier one:  dozer <- harvesters <- insignificant <- player <- alive
// <- team.  Read off the five link receivers, which the trace resolves to
// F+0x78, F+0x1C, F+0x30, F+0x28, F+0x00, with the first receiver coming from
// the dozer constructor's EAX and the first argument from the harvesters
// constructor's ESI.
//
// The affiliation 0xA is ALLOW_ALLIES|ALLOW_NEUTRAL: Zero Hour's PlayerList.h
// gives 0x02 and 0x08, and the EA source passes exactly that expression
// (AIPlayer.cpp:1032).  The third getClosestObject argument is 3, i.e.
// FROM_BOUNDINGSPHERE_3D (PartitionManager.h:155), pushed at 0x00163055.
//
// ============================================================================
// the mask, the result shape, and everything else already settled
// ============================================================================
// The mask spelling (memset the six dwords, then set one bit) is the one the
// matched AIPlayer::findSupplyCenter body uses (AIPlayerFindSupplyCenter.cpp,
// 886 B exact), and it is the only one that keeps retail's register-form
// `or eax, 0x4000`.  Six tracked field assignments fold the OR to a constant
// store (shape 0.772) and a real std::bitset<192> emits a zeroing loop.
//
// The two KindOf bits are 1<<14 and 1<<16, both in dword 0 of the 24-byte
// mask, read off the `or` immediates at 0x0016306A and 0x001630A0.  The shim's
// own enum has one fewer kind than retail's, so the NUMBERS are what is
// proved, not the names KINDOF_HARVESTER/KINDOF_DOZER.
//
// The result shape is retail's: `if (tthing == 0) return false;` followed by
// an unconditional tail, which emits the `xor al,al` at +0x2C with the `jmp`
// to the epilogue and the `neg eax / sbb al,al / inc al` normalisation.
//
// ============================================================================
// levers measured THIS session and rejected (all on the 0xB0-frame bank)
// ============================================================================
// f1  named `const Player *const pl = m_player` local        407 B  shape 0.843
// f2  sequential `filters = a.link(filters)` chain           393 B  IDENTICAL
// f3  named KindOf mask locals                               393 B  frame 0xB8
// f4  virtual ~PartitionFilter on the base                   425 B  frame 0xC8
// f5  f1 + f4                                                439 B  shape 0.764
// f6  `PartitionFilter *const harvesters = &filterHarvesters` 393 B IDENTICAL
// g1  virtual Bool allow(Object*) on the base                425 B  IDENTICAL to f4
// g2  separate VptrZeroBlockHead base with a virtual anchor  393 B  IDENTICAL
// h1  drop the named aiData local                            390 B  310 diffs
// h2  also name `AI *const ai = TheAI`                       393 B  IDENTICAL
// h5  swap the two KindOf declarations  (MECHANISM PROBE ONLY, NOT A CANDIDATE)
//     393 B but 220 diffs -- and that number is a byte-ALIGNMENT artifact of
//     the 2-byte `mov esi,eax` this build is missing, not real agreement; the
//     probe's own instruction-level diff list is byte-for-byte the same as the
//     bank, and the variant has the two KindOf immediates SWAPPED, which is
//     semantically wrong.  Do not bank it.
// i1  `AIPlayer *const self = this` named local              393 B  IDENTICAL
// i2  the four small filters declared before the two KindOf  409 B  frame 0xC4
// j1  five distinct `PartitionFilter *const` link temporaries 393 B  IDENTICAL
// eh_levers (throw() per callee, /EHsc-, _STLP_NO_EXCEPTIONS, nothrow delete[])
//     through shape_search, 8 trials: every trial is the bank, 0.3537.
// shape_family_levers over sib,register,bool,test,copy,store,loop,branch,
//     constant,frame through shape_search, 11 trials: the bank at 0.3537 plus
//     one variant at 0.3562 that swaps filterTeam's m_next/vptr store order.
//     That variant is REJECTED: retail writes m_next at +0xF5 and the vtable at
//     +0xF9, which is the order the bank already has, and the doc's "A
//     constructor's store order comes from the initializer list" makes the
//     observed order the evidence.  A 0.0025 masked-diff gain against the
//     evidence is metric optimisation, not progress.
//
// ============================================================================
// what landing this shape would additionally require
// ============================================================================
// The bank DEFINES the 0x00160BE0 constructor in this TU, which is a duplicate
// of the landed row's own definition, so it is a measurement form and must not
// be copied into game/ verbatim.  The landed precedent for this exact move is
// game/GameEngine/Source/GameLogic/Object/SpecialPower/Rva002622D0Collect.cpp:
// it defines its callee's constructor in the caller TU and symbols.csv pins the
// CALLEE'S mangled name at the ILT the retail call targets -- here
// `??0Rva00160BE0KindOfFilter@@QAE@ABUVptrZeroBlock24@@0@Z,0x00007E37` with a
// `route=0x00160BE0` note, because 0x00007E37 is a five-byte `jmp` thunk.  That
// is a distinct address from the landed body at 0x00160BE0, so it is not a
// second name on one address.  The class name must stay address-derived
// because the constructor's parameter types are unproven.  Before pinning:
// tools/pin_consistency.py --symbol, then --check after.
//
// ============================================================== what is left
// Size 393 vs 388, and all 5 bytes are the one missing register allocation
// described above: retail keeps the first constructor's return value in ESI
// (and therefore `this` in EDI), we fold both constructor results to frame
// constants and re-derive them with `lea`.  Proven here: the KindOf
// constructor's body preserves ESI, so a register IS available for that
// interval in retail; and the interval is not reachable from C++ that this
// compiler folds to a frame address, in nine different spellings.
// t=95min model=opencode/space-bunny-free
// blocker=regalloc/harvesters-pointer-esi-vs-frame-constant

#include <string.h>

extern "C" void *__cdecl memset(void *, int, unsigned int);
#pragma intrinsic(memset)

typedef bool Bool;
typedef int Int;
typedef unsigned int UnsignedInt;
typedef float Real;

struct Coord3D
{
	Real x;
	Real y;
	Real z;
};

class Object;
class Player;

class ThingTemplate
{
public:
	Real getBoundingCircleRadius(void) const
	{
		return *(const Real *)((const char *)this + 0x70);
	}
};

class AiData
{
public:
	char m_unmodelled000[0x84];
	Real m_supplyCenterSafeRadius;						// +0x84
};

class AI
{
public:
	char m_unmodelled000[0x14];
	AiData *m_aiData;									// +0x14
};

extern AI *TheAI;

// The 24-byte block the landed 0x00160BE0 constructor takes twice by const
// reference: two 192-bit KindOf masks, six dwords.
//
// The kInit/idx constructor is upstream BitFlags(BogusInitType, Int idx1)
// (inputs/reference/CnC_Generals_Zero_Hour/Generals/Code/GameEngine/Include/
// Common/BitFlags.h), whose body is m_bits.set(idx) on a std::bitset<192>.
// Modelling it on the parameter type itself keeps a mask a plain temporary of
// exactly the parameter type, so it binds to the by-reference argument with
// full-expression lifetime.
struct VptrZeroBlock24
{
	enum BogusInitType { kInit = 0 };

	unsigned int bits[6];

	VptrZeroBlock24(void)
	{
		bits[0] = 0;
		bits[1] = 0;
		bits[2] = 0;
		bits[3] = 0;
		bits[4] = 0;
		bits[5] = 0;
	}

	VptrZeroBlock24(BogusInitType, Int bit)
	{
		memset(bits, 0, sizeof(bits));
		bits[bit >> 5] |= (1U << (bit & 31));
	}
};

extern const VptrZeroBlock24 KINDOFMASK_NONE;

// The immediates are 1<<14 and 1<<16 in dword 0 of the mask.  The shim's enum
// has one fewer kind than retail's, so these numbers -- not the names -- are
// what the body proves.
enum BFME_KindOfFromRetailMasks
{
	KINDOF_HARVESTER = 14,
	KINDOF_DOZER = 16
};

#define MAKE_KINDOF_MASK(k) VptrZeroBlock24(VptrZeroBlock24::kInit, (k))

// PlayerList.h relationship flags: ALLOW_ALLIES 0x02, ALLOW_NEUTRAL 0x08.
enum AllowPlayerRelationship
{
	ALLOW_ALLIES = 0x02,
	ALLOW_NEUTRAL = 0x08
};

// PartitionManager.h:155, the immediate retail pushes at 0x00163055.
enum DistanceCalculationType
{
	FROM_BOUNDINGSPHERE_2D = 2,
	FROM_BOUNDINGSPHERE_3D = 3
};

class PartitionFilter
{
public:
	PartitionFilter(void) {}
	PartitionFilter *link(PartitionFilter *next);

	unsigned int m_vptr;
	PartitionFilter *m_next;
};

// The complete, independently matched 102-byte body at 0x00160BE0, defined
// HERE on purpose: seeing that it copies both masks and retains neither
// reference is what lets VC7.1 free the mask temporary's 0x18 bytes for
// filterTeam and reproduce retail's exact 0xB0 frame (see the header).  The
// store order and the push esi / pop esi pair are the landed body's.
//
// Address-derived name: vtable 0x0109686C is proven to be
// PartitionFilterRejectByKindOf and the matched
// PartitionFilterRejectByKindOf::allow reads its two masks at this+0x08 and
// this+0x20, which are the two offsets copied to below -- so the LAYOUT is
// that class's -- but the constructor's parameter TYPES are not proved, and
// this class name must not collide with the two TUs that already declare the
// real one.
class Rva00160BE0KindOfFilter : public PartitionFilter
{
public:
	__declspec(noinline) Rva00160BE0KindOfFilter(
		const VptrZeroBlock24 &first, const VptrZeroBlock24 &second)
		: m_first(first), m_second(second)
	{
		m_next = 0;
		m_vptr = 0x0109686C;
	}

	~Rva00160BE0KindOfFilter(void)
	{
		m_vptr = 0x01083B5C;
	}

	VptrZeroBlock24 m_first;							// +0x08
	VptrZeroBlock24 m_second;							// +0x20
};

class PartitionFilterInsignificantBuildings : public PartitionFilter
{
public:
	PartitionFilterInsignificantBuildings(Bool allowNonBuildings, Bool allowInsignificant)
		: PartitionFilter()
	{
		m_next = 0;
		m_vptr = 0x010956E4;
		m_allowNonBuildings = allowNonBuildings;
		m_allowInsignificant = allowInsignificant;
	}

	~PartitionFilterInsignificantBuildings(void)
	{
		m_vptr = 0x01083B5C;
	}

	Bool m_allowNonBuildings;
	Bool m_allowInsignificant;
};

// vtable 0x0109685C, m_player +0x08, m_match +0x0C.
class PartitionFilterPlayer : public PartitionFilter
{
public:
	PartitionFilterPlayer(const Player *player, Bool match)
		: PartitionFilter()
	{
		m_next = 0;
		m_vptr = 0x0109685C;
		m_player = player;
		m_match = match;
	}

	~PartitionFilterPlayer(void)
	{
		m_vptr = 0x01083B5C;
	}

	const Player *m_player;
	Bool m_match;
};

class PartitionFilterAlive : public PartitionFilter
{
public:
	PartitionFilterAlive(void) : PartitionFilter()
	{
		m_next = 0;
		m_vptr = 0x01083B80;
	}

	~PartitionFilterAlive(void)
	{
		m_vptr = 0x01083B5C;
	}
};

class PartitionFilterPlayerAffiliation : public PartitionFilter
{
public:
	PartitionFilterPlayerAffiliation(const Player *player, UnsignedInt affiliation, Bool match)
		: PartitionFilter()
	{
		m_next = 0;
		m_vptr = 0x0109689C;
		m_player = player;
		m_match = match;
		m_affiliation = affiliation;
	}

	~PartitionFilterPlayerAffiliation(void)
	{
		m_vptr = 0x01083B5C;
	}

	const Player *m_player;
	Bool m_match;
	UnsignedInt m_affiliation;
};

class PartitionManager
{
public:
	Object *getClosestObject(const Coord3D *position, Real maxDistance,
		Int distanceCalculation, PartitionFilter *filters);
};

extern PartitionManager *ThePartitionManager;

class AIPlayer
{
public:
	Bool isLocationSafe(const Coord3D *pos, const ThingTemplate *tthing);

	char m_unmodelled000[0x0c];
	Player *m_player;									// +0x0C
};

Bool AIPlayer::isLocationSafe(const Coord3D *pos, const ThingTemplate *tthing)
{
	if (tthing == 0)
		return false;
	{
		AiData *const aiData = TheAI->m_aiData;
		Real radius = tthing->getBoundingCircleRadius() +
			aiData->m_supplyCenterSafeRadius;

		Rva00160BE0KindOfFilter filterHarvesters(
			MAKE_KINDOF_MASK(KINDOF_HARVESTER), KINDOFMASK_NONE);

		Rva00160BE0KindOfFilter filterDozer(
			MAKE_KINDOF_MASK(KINDOF_DOZER), KINDOFMASK_NONE);

		PartitionFilterInsignificantBuildings filterInsignificant(true, false);
		PartitionFilterPlayer filterPlayer(m_player, false);
		PartitionFilterAlive filterAlive;
		PartitionFilterPlayerAffiliation filterTeam(
			m_player, ALLOW_ALLIES | ALLOW_NEUTRAL, false);

		PartitionFilter *filters = filterTeam.link(
			filterAlive.link(
				filterPlayer.link(
					filterInsignificant.link(
						filterDozer.link(&filterHarvesters)))));

		Object *enemy = ThePartitionManager->getClosestObject(
			pos, radius, FROM_BOUNDINGSPHERE_3D, filters);
		return enemy == 0;
	}
}
